// utils/css-variables.ts
import { designTokens } from '../tokens/design-tokens';
import { cloverTokens } from '../tokens/clover-tokens';

export function generateCSSVariables(tokens: typeof designTokens): string {
  const lines: string[] = [':root {'];

  // Colors
  Object.entries(tokens.colors).forEach(([category, values]) => {
    if (typeof values === 'object' && !Array.isArray(values)) {
      Object.entries(values).forEach(([key, value]) => {
        if (typeof value === 'string') {
          lines.push(`  --color-${category}-${key}: ${value};`);
        } else if (typeof value === 'object') {
          Object.entries(value).forEach(([subKey, subValue]) => {
            lines.push(`  --color-${category}-${key}-${subKey}: ${subValue};`);
          });
        }
      });
    }
  });

  // Spacing
  Object.entries(tokens.spacing).forEach(([key, value]) => {
    lines.push(`  --spacing-${key}: ${value};`);
  });

  // Typography
  Object.entries(tokens.typography.fontFamilies).forEach(([key, value]) => {
    lines.push(`  --font-family-${key}: ${value};`);
  });
  Object.entries(tokens.typography.fontSizes).forEach(([key, value]) => {
    lines.push(`  --font-size-${key}: ${value};`);
  });
  Object.entries(tokens.typography.fontWeights).forEach(([key, value]) => {
    lines.push(`  --font-weight-${key}: ${value};`);
  });
  Object.entries(tokens.typography.lineHeights).forEach(([key, value]) => {
    lines.push(`  --line-height-${key}: ${value};`);
  });
  Object.entries(tokens.typography.letterSpacings).forEach(([key, value]) => {
    lines.push(`  --letter-spacing-${key}: ${value};`);
  });

  // Border Radius
  Object.entries(tokens.borderRadius).forEach(([key, value]) => {
    lines.push(`  --radius-${key}: ${value};`);
  });

  // Shadows
  Object.entries(tokens.shadows).forEach(([key, value]) => {
    lines.push(`  --shadow-${key}: ${value};`);
  });

  // Z-Index
  Object.entries(tokens.zIndex).forEach(([key, value]) => {
    lines.push(`  --z-${key}: ${value};`);
  });

  // Transitions
  Object.entries(tokens.transitions).forEach(([key, value]) => {
    lines.push(`  --transition-${key}: ${value};`);
  });

  // Breakpoints
  Object.entries(tokens.breakpoints).forEach(([key, value]) => {
    lines.push(`  --breakpoint-${key}: ${value};`);
  });

  // Clover-specific tokens
  lines.push('  /* Clover Aesthetic Tokens */');
  lines.push(`  --clover-leaf-radius: ${cloverTokens.leaf.radius};`);
  lines.push(`  --clover-leaf-overlap: ${cloverTokens.leaf.overlap};`);
  lines.push(`  --clover-leaf-rotation: ${cloverTokens.leaf.rotation}deg;`);
  lines.push(`  --clover-leaf-count: ${cloverTokens.leaf.count};`);
  lines.push(`  --clover-stem-width: ${cloverTokens.stem.width};`);
  lines.push(`  --clover-stem-height: ${cloverTokens.stem.height};`);
  lines.push(`  --clover-stem-radius: ${cloverTokens.stem.borderRadius};`);
  lines.push(`  --clover-container-min-size: ${cloverTokens.container.minSize};`);
  lines.push(`  --clover-container-max-size: ${cloverTokens.container.maxSize};`);
  lines.push(`  --clover-animation-bloom: ${cloverTokens.animation.bloom};`);
  lines.push(`  --clover-animation-settle: ${cloverTokens.animation.settle};`);
  lines.push(`  --clover-animation-pulse: ${cloverTokens.animation.pulse};`);

  lines.push('}');

  // Dark mode
  lines.push('');
  lines.push('@media (prefers-color-scheme: dark) {');
  lines.push('  :root {');
  lines.push('    --color-background-primary: #18181b;');
  lines.push('    --color-background-secondary: #27272a;');
  lines.push('    --color-background-tertiary: #3f3f46;');
  lines.push('    --color-background-inverse: #ffffff;');
  lines.push('    --color-surface-primary: #27272a;');
  lines.push('    --color-surface-secondary: #3f3f46;');
  lines.push('    --color-surface-tertiary: #52525b;');
  lines.push('    --color-surface-elevated: #3f3f46;');
  lines.push('    --color-border-primary: #3f3f46;');
  lines.push('    --color-border-secondary: #52525b;');
  lines.push('    --color-text-primary: #fafafa;');
  lines.push('    --color-text-secondary: #a1a1aa;');
  lines.push('    --color-text-tertiary: #71717a;');
  lines.push('    --color-text-inverse: #18181b;');
  lines.push('    --color-text-disabled: #52525b;');
  lines.push('  }');
  lines.push('}');

  return lines.join('\n');
}

